// Generated by Rustier. Publish target packages before the root package.
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const directory = dirname(fileURLToPath(import.meta.url));
const plan = JSON.parse(readFileSync(resolve(directory, 'packages.json'), 'utf8'));
const root = resolve(directory, plan.root);
const metadata = JSON.parse(readFileSync(resolve(root, 'package.json'), 'utf8'));
const cli = process.env.npm_execpath;

if (!cli || !/npm-cli\.js$/.test(cli)) throw new Error('Run this release through npm publish');
if (metadata.private) throw new Error('Cannot publish native packages for a private root package');
if (metadata.version !== plan.version) throw new Error('Rebuild Rustier packages after changing the root version');

const dryRun = ['true', '1'].includes(process.env.npm_config_dry_run);
const settings = {
  tag: process.env.npm_config_tag || metadata.publishConfig?.tag || 'latest',
  registry: process.env.npm_config_registry || metadata.publishConfig?.registry,
  access: process.env.npm_config_access || metadata.publishConfig?.access,
};
const flags = Object.entries(settings).flatMap(([key, value]) => value ? ['--' + key, value] : []);

function npm(args, cwd) {
  const result = spawnSync(process.execPath, [cli, ...args], { cwd, encoding: 'utf8', env: process.env });
  if (result.error) throw result.error;
  return result;
}

function json(result) {
  if (result.status !== 0) throw new Error(result.stderr || result.stdout || 'npm command failed');
  return JSON.parse(result.stdout);
}

const rootPack = json(npm(['pack', '--dry-run', '--json', '--ignore-scripts'], root))[0];
if (rootPack.files.some(file => file.path.startsWith(plan.packageDir + '/'))) {
  throw new Error('Exclude ' + plan.packageDir + ' from the root package files before publishing');
}

// Validate every package before publishing any of them.
const packages = plan.packages.map(entry => {
  const cwd = resolve(directory, entry.directory);
  const pkg = JSON.parse(readFileSync(resolve(cwd, 'package.json'), 'utf8'));

  if (pkg.name !== entry.name || pkg.version !== plan.version || !pkg.rustierGenerated) {
    throw new Error('Generated package metadata changed: ' + entry.name);
  }

  const packed = json(npm(['pack', '--dry-run', '--json', '--ignore-scripts'], cwd))[0];
  if (packed.integrity !== entry.integrity) throw new Error('Rebuild modified package ' + entry.name);

  return { ...entry, cwd };
});

for (const entry of packages) {
  if (!dryRun) {
    const registryFlags = settings.registry ? ['--registry', settings.registry] : [];
    const existing = npm(['view', entry.name + '@' + plan.version, 'dist.integrity', '--json', ...registryFlags], root);

    if (existing.status === 0) {
      if (JSON.parse(existing.stdout) !== entry.integrity) throw new Error('Published package differs: ' + entry.name);
      console.log('Already published ' + entry.name + '@' + plan.version);
      continue;
    }

    let code;
    try { code = JSON.parse(existing.stdout).error?.code; } catch {}
    if (code !== 'E404') throw new Error(existing.stderr || existing.stdout);
  }

  const result = npm(['publish', '--ignore-scripts', ...flags, ...(dryRun ? ['--dry-run'] : [])], entry.cwd);
  process.stdout.write(result.stdout || '');
  process.stderr.write(result.stderr || '');
  if (result.status !== 0) throw new Error('Could not publish ' + entry.name);
}
